public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // n 개의 스레드에서 body(스레드 번호)를 동시에 실행한다. 예외와 시간 초과는 사유 문자열로 돌려준다.
    static string Parallel(int n, int timeoutMs, System.Action<int> body)
    {
        string error = null;
        int go = 0, ready = 0;
        var threads = new System.Threading.Thread[n];
        for (int i = 0; i < n; i++)
        {
            int idx = i;
            threads[i] = new System.Threading.Thread(() =>
            {
                try
                {
                    System.Threading.Interlocked.Increment(ref ready);
                    while (System.Threading.Volatile.Read(ref go) == 0) System.Threading.Thread.Yield();
                    body(idx);
                }
                catch (System.Exception e) { System.Threading.Interlocked.CompareExchange(ref error, "워커 스레드에서 예외 발생: " + e.GetType().Name, null); }
            });
            threads[i].IsBackground = true;
            threads[i].Start();
        }
        var sw = System.Diagnostics.Stopwatch.StartNew();
        // 모든 스레드가 출발선에 설 때까지 기다렸다가 동시에 출발시킨다
        while (System.Threading.Volatile.Read(ref ready) < n && sw.ElapsedMilliseconds < 1000) System.Threading.Thread.Sleep(1);
        System.Threading.Volatile.Write(ref go, 1);
        foreach (var t in threads)
        {
            int left = timeoutMs - (int)sw.ElapsedMilliseconds;
            if (left < 1 || !t.Join(left)) return "시간 초과(" + timeoutMs + "ms): 스레드가 끝나지 않음(락을 풀지 않았거나 교착)";
        }
        return error;
    }

    public static void Main()
    {
        Run("single-thread-basic", () =>
        {
            var l = new LootLedger();
            if (l.TotalGold != 0 || l.DropCount != 0 || l.SnapshotDrops().Length != 0) return "빈 장부의 초기값이 0 이 아님";
            l.AddGold(30); l.AddGold(12); l.AddDrop(7); l.AddDrop(3); l.AddDrop(7);
            if (l.TotalGold != 42) return "AddGold(30), AddGold(12) 후 기대 42 / 결과 " + l.TotalGold;
            int[] s = l.SnapshotDrops();
            if (l.DropCount != 3 || s.Length != 3 || s[0] != 7 || s[1] != 3 || s[2] != 7) return "AddDrop 7,3,7 후 스냅샷이 [7,3,7] 이 아님";
            s[0] = 99;
            if (l.SnapshotDrops()[0] != 7) return "SnapshotDrops 가 복사본이 아니라 내부 저장소를 노출함";
            if (!l.TryClaimFirstKill()) return "첫 TryClaimFirstKill 이 false";
            if (l.TryClaimFirstKill()) return "두 번째 TryClaimFirstKill 이 true";
            return null;
        });

        Run("gold-concurrent-sum", () =>
        {
            for (int round = 0; round < 3; round++)
            {
                var l = new LootLedger();
                const int threads = 4, per = 1000000;
                string e = Parallel(threads, 2500, t => { for (int k = 0; k < per; k++) l.AddGold(1 + (k & 1)); });
                if (e != null) return e;
                long expected = (long)threads * (per / 2) * 3;
                if (l.TotalGold != expected) return "스레드 4개 x AddGold 100만 회: 기대 " + expected + " / 결과 " + l.TotalGold + " (갱신 유실)";
            }
            return null;
        });

        Run("drops-concurrent-no-loss", () =>
        {
            for (int round = 0; round < 3; round++)
            {
                var l = new LootLedger();
                const int threads = 4, per = 50000;
                string e = Parallel(threads, 2000, t => { for (int k = 0; k < per; k++) l.AddDrop(t * per + k); });
                if (e != null) return e;
                int[] s = l.SnapshotDrops();
                if (l.DropCount != threads * per || s.Length != threads * per) return "스레드 4개 x AddDrop 5만 회: 기대 " + (threads * per) + "개 / 결과 " + s.Length + "개";
                var seen = new bool[threads * per];
                foreach (int id in s)
                {
                    if (id < 0 || id >= seen.Length || seen[id]) return "스냅샷에 넣은 적 없는 값이나 중복이 있음: " + id;
                    seen[id] = true;
                }
            }
            return null;
        });

        Run("drops-per-thread-order", () =>
        {
            var l = new LootLedger();
            const int threads = 2, per = 60000;
            string e = Parallel(threads, 2000, t => { for (int k = 0; k < per; k++) l.AddDrop(t * per + k); });
            if (e != null) return e;
            var next = new int[threads];
            foreach (int id in l.SnapshotDrops())
            {
                int t = id / per;
                if (id < 0 || t >= threads || id % per != next[t]) return "한 스레드가 넣은 순서가 스냅샷에서 깨짐(값 " + id + ")";
                next[t]++;
            }
            return next[0] == per && next[1] == per ? null : "일부 드롭이 유실됨";
        });

        Run("snapshot-while-adding", () =>
        {
            var l = new LootLedger();
            const int per = 80000;
            string bad = null;
            int writersDone = 0;
            string e = Parallel(3, 2000, t =>
            {
                if (t < 2)
                {
                    try { for (int k = 0; k < per; k++) l.AddDrop(t * per + k); }
                    finally { System.Threading.Interlocked.Increment(ref writersDone); }
                    return;
                }
                int last = 0;
                // 기록 스레드가 도는 동안만 스냅샷을 찍고(최대 400회), 끝난 뒤 한 번 더 찍는다
                for (int k = 0; k < 400 && bad == null; k++)
                {
                    bool final = System.Threading.Volatile.Read(ref writersDone) == 2;
                    int[] s = l.SnapshotDrops();
                    if (s.Length < last) bad = "스냅샷 길이가 줄어듦: " + last + " -> " + s.Length;
                    last = s.Length;
                    var next = new int[2];
                    foreach (int id in s)
                    {
                        int w = id / per;
                        if (id < 0 || w >= 2 || id % per != next[w]) { bad = "쓰기 도중의 스냅샷이 일관되지 않음(값 " + id + ")"; break; }
                        next[w]++;
                    }
                    if (final) break;
                }
            });
            if (e != null) return e;
            if (bad != null) return bad;
            return l.DropCount == 2 * per ? null : "기대 " + (2 * per) + "개 / 결과 " + l.DropCount + "개";
        });

        Run("first-kill-single-winner", () =>
        {
            const int rounds = 50000;
            var ledgers = new LootLedger[rounds];
            for (int i = 0; i < rounds; i++) ledgers[i] = new LootLedger();
            var arrived = new int[rounds];
            var wins = new int[rounds];
            // 두 스레드가 라운드마다 서로를 잠깐(제한된 횟수만) 기다렸다가 거의 동시에 수령을 시도한다.
            // 기다림에 상한이 있으므로 한 스레드가 늦게 스케줄되어도 멈추지 않는다.
            string e = Parallel(2, 3000, t =>
            {
                for (int r = 0; r < rounds; r++)
                {
                    System.Threading.Interlocked.Increment(ref arrived[r]);
                    for (int spin = 0; spin < 400 && System.Threading.Volatile.Read(ref arrived[r]) < 2; spin++) System.Threading.Thread.SpinWait(1);
                    if (ledgers[r].TryClaimFirstKill()) System.Threading.Interlocked.Increment(ref wins[r]);
                }
            });
            if (e != null) return e;
            int doubled = 0, none = 0;
            for (int r = 0; r < rounds; r++) { if (wins[r] > 1) doubled++; else if (wins[r] == 0) none++; }
            if (none > 0) return "아무도 보너스를 받지 못한 장부가 " + none + "개";
            return doubled == 0 ? null : "장부 " + rounds + "개 중 " + doubled + "개에서 두 스레드가 모두 true 를 받음(중복 지급)";
        });
    }
}

