public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Threading.Thread Spawn(System.Action body)
    {
        var t = new System.Threading.Thread(() => { try { body(); } catch (System.Exception) { } });
        t.IsBackground = true;   // 교착에 빠져도 프로세스 종료를 막지 않는다
        t.Start();
        return t;
    }

    // 스레드가 락 대기 상태에 들어가거나 끝날 때까지(최대 1초) 기다린다.
    static void WaitBlockedOrDone(System.Threading.Thread t)
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        while (sw.ElapsedMilliseconds < 1000)
        {
            if (!t.IsAlive || (t.ThreadState & System.Threading.ThreadState.WaitSleepJoin) != 0) break;
            System.Threading.Thread.Sleep(1);
        }
        System.Threading.Thread.Sleep(20);
    }

    // 심판이 OwnerId 가 작은 쪽(low)의 Gate 를 쥔 상태에서 from -> to 거래를 시작시키고,
    // 거래 스레드가 low 를 기다리는 동안 OwnerId 가 큰 쪽(high)의 Gate 를 쥐고 있는지 본다.
    // 쥐고 있다면 "high 를 쥐고 low 를 기다리는" 스레드가 존재한다는 뜻이고, 타이밍과 무관하게 항상 재현된다.
    static string ProbeOrder(int fromId, int toId)
    {
        var from = new Inventory(fromId, 100); var to = new Inventory(toId, 100);
        Inventory low = fromId < toId ? from : to, high = fromId < toId ? to : from;
        System.Threading.Thread t;
        bool highHeld;
        lock (low.Gate)
        {
            t = Spawn(() => TradeService.Transfer(from, to, 10));
            WaitBlockedOrDone(t);
            highHeld = !System.Threading.Monitor.TryEnter(high.Gate);
            if (!highHeld) System.Threading.Monitor.Exit(high.Gate);
        }
        if (!t.Join(2000)) return "시간 초과(2000ms): 락을 풀어 줘도 OwnerId " + fromId + " -> " + toId + " 거래가 끝나지 않음";
        if (highHeld) return "OwnerId " + fromId + " -> " + toId + " 거래가 OwnerId " + high.OwnerId + " 의 Gate 를 먼저 쥔 채 " + low.OwnerId + " 의 Gate 를 기다림(요구 스펙 1 의 락 순서 위반)";
        if (from.Gold != 90 || to.Gold != 110) return "OwnerId " + fromId + " -> " + toId + " 로 10 이체: 기대 90/110 / 결과 " + from.Gold + "/" + to.Gold;
        return null;
    }

    // 모든 스레드를 합쳐 timeoutMs 안에 끝나는지 확인한다.
    static bool JoinAll(System.Threading.Thread[] ts, int timeoutMs)
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        foreach (var t in ts)
        {
            int left = timeoutMs - (int)sw.ElapsedMilliseconds;
            if (left < 1 || !t.Join(left)) return false;
        }
        return true;
    }

    public static void Main()
    {
        Run("basic-transfer", () =>
        {
            var a = new Inventory(1, 100); var b = new Inventory(2, 5);
            if (!TradeService.Transfer(a, b, 30)) return "잔액 100 에서 30 이체가 false";
            if (a.Gold != 70 || b.Gold != 35) return "이체 30 후 기대 70/35 / 결과 " + a.Gold + "/" + b.Gold;
            if (!TradeService.Transfer(b, a, 35)) return "잔액 전부(35) 이체가 false";
            if (a.Gold != 105 || b.Gold != 0) return "역방향 이체 후 기대 105/0 / 결과 " + a.Gold + "/" + b.Gold;
            return null;
        });

        Run("reject-invalid", () =>
        {
            var a = new Inventory(1, 100); var b = new Inventory(2, 50);
            if (TradeService.Transfer(a, b, 101)) return "잔액 100 에서 101 이체가 true";
            if (TradeService.Transfer(a, b, 0)) return "amount 0 이체가 true";
            if (TradeService.Transfer(a, b, -40)) return "amount -40 이체가 true (음수로 상대 골드를 빼 옴)";
            if (TradeService.Transfer(a, a, 10)) return "자기 자신과의 거래가 true";
            if (a.Gold != 100 || b.Gold != 50) return "거절된 거래가 잔액을 바꿈: 기대 100/50 / 결과 " + a.Gold + "/" + b.Gold;
            return null;
        });

        Run("lock-order-by-owner-id", () =>
        {
            // 여러 쌍을 양방향으로 확인한다. 올바른 순서라면 어느 방향이든 작은 쪽을 기다리는 동안 큰 쪽의 락을 쥐고 있지 않다.
            int[,] pairs = { { 20, 10 }, { 10, 20 }, { 7, 3 }, { 3, 7 }, { 1000, 999 }, { 999, 1000 }, { 4, 50 }, { 50, 4 } };
            for (int i = 0; i < pairs.GetLength(0); i++)
            {
                string e = ProbeOrder(pairs[i, 0], pairs[i, 1]);
                if (e != null) return e;
            }
            return null;
        });

        Run("balance-check-inside-lock", () =>
        {
            // 잔액 100 에서 60 씩 두 번: 한 번만 성공해야 한다. 심판이 락 하나를 쥔 동안 두 요청이 모두 대기하게 만든다.
            // 보내는 쪽의 OwnerId 가 작은 경우와 큰 경우를 모두 본다(잔액 검사가 두 락 밖에 있으면 둘 중 하나에서 반드시 드러난다).
            for (int round = 0; round < 2; round++)
            {
                var a = new Inventory(round == 0 ? 1 : 2, 100); var b = new Inventory(round == 0 ? 2 : 1, 0);
                Inventory held = round == 0 ? a : b;   // 두 번 모두 OwnerId 가 작은 쪽
                int ok = 0;
                var ts = new System.Threading.Thread[2];
                lock (held.Gate)
                {
                    for (int i = 0; i < 2; i++)
                    {
                        ts[i] = Spawn(() => { if (TradeService.Transfer(a, b, 60)) System.Threading.Interlocked.Increment(ref ok); });
                        WaitBlockedOrDone(ts[i]);
                    }
                }
                if (!JoinAll(ts, 2000)) return "시간 초과(2000ms): 거래가 끝나지 않음";
                if (ok != 1 || a.Gold != 40 || b.Gold != 60)
                    return "잔액 100 인 플레이어(OwnerId " + a.OwnerId + ")가 OwnerId " + b.OwnerId + " 에게 60 이체 2건 동시 요청: 기대 성공 1건, 40/60 / 결과 성공 " + ok + "건, " + a.Gold + "/" + b.Gold;
            }
            return null;
        });

        Run("opposite-trades-no-deadlock", () =>
        {
            // 먼저 타이밍과 무관한 검사: 두 방향 모두 "큰 쪽을 쥐고 작은 쪽을 기다리는" 순간이 없어야 한다.
            string probe = ProbeOrder(2, 1) ?? ProbeOrder(1, 2);
            if (probe != null) return "A->B 와 B->A 가 만나면 교착될 수 있음: " + probe;
            var a = new Inventory(1, 1000); var b = new Inventory(2, 1000);
            int go = 0;
            System.Func<Inventory, Inventory, System.Threading.Thread> worker = (x, y) => Spawn(() =>
            {
                while (System.Threading.Volatile.Read(ref go) == 0) System.Threading.Thread.Yield();
                for (int k = 0; k < 50000; k++) TradeService.Transfer(x, y, 1);
            });
            var ts = new[] { worker(a, b), worker(b, a) };
            System.Threading.Thread.Sleep(30);
            System.Threading.Volatile.Write(ref go, 1);
            if (!JoinAll(ts, 2500)) return "시간 초과(2500ms): A->B 와 B->A 거래가 서로를 기다리며 멈춤(교착)";
            if (a.Gold + b.Gold != 2000 || a.Gold < 0 || b.Gold < 0) return "골드 총합 기대 2000 / 결과 " + a.Gold + " + " + b.Gold;
            return null;
        });

        Run("three-way-ring-no-deadlock", () =>
        {
            string probe = ProbeOrder(3, 1) ?? ProbeOrder(1, 2) ?? ProbeOrder(2, 3);
            if (probe != null) return "A->B, B->C, C->A 가 만나면 교착될 수 있음: " + probe;
            var inv = new[] { new Inventory(3, 500), new Inventory(1, 500), new Inventory(2, 500) };
            int go = 0;
            var ts = new System.Threading.Thread[3];
            for (int i = 0; i < 3; i++)
            {
                Inventory x = inv[i], y = inv[(i + 1) % 3];
                ts[i] = Spawn(() =>
                {
                    while (System.Threading.Volatile.Read(ref go) == 0) System.Threading.Thread.Yield();
                    for (int k = 0; k < 30000; k++) TradeService.Transfer(x, y, 1);
                });
            }
            System.Threading.Thread.Sleep(30);
            System.Threading.Volatile.Write(ref go, 1);
            if (!JoinAll(ts, 2500)) return "시간 초과(2500ms): A->B, B->C, C->A 순환 거래가 멈춤(교착)";
            int sum = inv[0].Gold + inv[1].Gold + inv[2].Gold;
            return sum == 1500 ? null : "골드 총합 기대 1500 / 결과 " + sum;
        });

        Run("random-trades-conserve-gold", () =>
        {
            var inv = new Inventory[5];
            for (int i = 0; i < 5; i++) inv[i] = new Inventory(i * 7 % 5 + 1, 300);
            int go = 0;
            var ts = new System.Threading.Thread[4];
            for (int i = 0; i < 4; i++)
            {
                int seed = 1000 + i;
                ts[i] = Spawn(() =>
                {
                    var rng = new System.Random(seed);
                    while (System.Threading.Volatile.Read(ref go) == 0) System.Threading.Thread.Yield();
                    for (int k = 0; k < 20000; k++) TradeService.Transfer(inv[rng.Next(5)], inv[rng.Next(5)], rng.Next(-5, 120));
                });
            }
            System.Threading.Thread.Sleep(30);
            System.Threading.Volatile.Write(ref go, 1);
            if (!JoinAll(ts, 2500)) return "시간 초과(2500ms): 무작위 거래 도중 멈춤(교착)";
            int sum = 0;
            foreach (var v in inv) { if (v.Gold < 0) return "잔액이 음수가 됨: " + v.Gold; sum += v.Gold; }
            return sum == 1500 ? null : "골드 총합 기대 1500 / 결과 " + sum;
        });
    }
}

