problems.solutionCode:
using System;
using System.Collections.Generic;
using System.Threading;

// 워커 스레드가 맡긴 작업을 "메인 스레드"가 프레임마다 한 번씩 꺼내 실행한다.
public sealed class MainThreadDispatcher
{
    private readonly object _gate = new object();
    private readonly int _mainThreadId;
    private readonly Action<Exception> _onError;
    private List<Action> _pending = new List<Action>();   // _gate 로 보호. 워커가 채운다
    private List<Action> _running = new List<Action>();   // 메인 스레드만 만진다
    private bool _pumping;                                // 메인 스레드만 만진다

    // 이 생성자를 호출한 스레드가 메인 스레드다. onError 는 null 일 수 있다.
    public MainThreadDispatcher(Action<Exception> onError)
    {
        _mainThreadId = Environment.CurrentManagedThreadId;
        _onError = onError;
    }

    // 아직 실행되지 않고 대기 중인 작업 수.
    public int PendingCount
    {
        get { lock (_gate) { return _pending.Count; } }
    }

    // 어느 스레드에서든 호출할 수 있다. action 이 null 이면 ArgumentNullException.
    public void Post(Action action)
    {
        if (action == null) throw new ArgumentNullException(nameof(action));
        lock (_gate) { _pending.Add(action); }
    }

    // 메인 스레드에서 프레임당 한 번 호출한다. 이 호출이 시작될 때 대기 중이던 작업만
    // 들어온 순서대로 실행하고, 실행한 작업 수(예외를 던진 작업 포함)를 반환한다.
    public int Pump()
    {
        if (Environment.CurrentManagedThreadId != _mainThreadId)
            throw new InvalidOperationException("Pump must be called from the main thread.");
        if (_pumping)
            throw new InvalidOperationException("Pump is not re-entrant.");

        // 락 안에서는 리스트 두 개를 맞바꾸기만 한다. 이후 들어오는 Post 는 새 _pending 에 쌓여 다음 Pump 로 넘어간다.
        lock (_gate)
        {
            List<Action> batch = _pending;
            _pending = _running;
            _running = batch;
        }

        _pumping = true;
        int count = _running.Count;
        try
        {
            // 작업은 락 밖에서 실행한다: 작업이 오래 걸려도 다른 스레드의 Post 를 막지 않는다.
            for (int i = 0; i < count; i++)
            {
                try { _running[i](); }
                catch (Exception e)
                {
                    if (_onError != null) _onError(e);   // 한 작업의 예외가 나머지를 잃게 하지 않는다
                }
            }
        }
        finally
        {
            _running.Clear();   // 용량은 남겨 다음 프레임에 재사용한다
            _pumping = false;
        }
        return count;
    }
}

