using System;

// 유닛 헤더를 32비트 하나에 담는다. 비트 0 이 최하위 비트(LSB)다.
//   비트  0– 1 (2비트): team   0–3
//   비트  2– 5 (4비트): class  0–15
//   비트  6–12 (7비트): level  0–127
//   비트 13–20 (8비트): flags  0–255
//   비트 21–31: 사용하지 않음(Pack 결과에서는 항상 0)
public static class UnitHeader
{
    private const int TeamShift = 0, ClassShift = 2, LevelShift = 6, FlagsShift = 13;
    // 시프트하기 전의 마스크: 필드 폭만큼 1 이 채워진 값
    private const uint TeamMask = 0x3, ClassMask = 0xF, LevelMask = 0x7F, FlagsMask = 0xFF;

    // 범위를 벗어난 값이 하나라도 있으면 ArgumentOutOfRangeException.
    public static uint Pack(int team, int unitClass, int level, byte flags)
    {
        if (team < 0 || team > (int)TeamMask) throw new ArgumentOutOfRangeException(nameof(team));
        if (unitClass < 0 || unitClass > (int)ClassMask) throw new ArgumentOutOfRangeException(nameof(unitClass));
        if (level < 0 || level > (int)LevelMask) throw new ArgumentOutOfRangeException(nameof(level));

        return ((uint)team << TeamShift)
             | ((uint)unitClass << ClassShift)
             | ((uint)level << LevelShift)
             | ((uint)flags << FlagsShift);
    }

    // 꺼낼 때는 오른쪽으로 민 다음 필드 폭만큼 마스크한다.
    // 다른 필드와 사용하지 않는 상위 비트는 결과에 영향을 주지 않는다.
    public static int GetTeam(uint packed) { return (int)((packed >> TeamShift) & TeamMask); }
    public static int GetClass(uint packed) { return (int)((packed >> ClassShift) & ClassMask); }
    public static int GetLevel(uint packed) { return (int)((packed >> LevelShift) & LevelMask); }
    public static byte GetFlags(uint packed) { return (byte)((packed >> FlagsShift) & FlagsMask); }

    // level 필드만 바꾼 새 값을 반환한다. 나머지 비트(사용하지 않는 상위 비트 포함)는 그대로 둔다.
    // level 이 0–127 을 벗어나면 ArgumentOutOfRangeException.
    public static uint WithLevel(uint packed, int level)
    {
        if (level < 0 || level > (int)LevelMask) throw new ArgumentOutOfRangeException(nameof(level));
        uint cleared = packed & ~(LevelMask << LevelShift);   // 1) 그 자리를 0 으로 비우고
        return cleared | ((uint)level << LevelShift);         // 2) 새 값을 OR 로 채운다
    }
}

