            return null;
        });

        Run("hit-registry-basic", () =>
        {
            var r = new HitRegistry();
            if (r.Count != 0) return "새 HitRegistry 의 Count 가 0 이 아님";
            if (!r.TryRegisterHit(7) || !r.TryRegisterHit(8) || !r.TryRegisterHit(-7) || !r.TryRegisterHit(0)) return "처음 맞는 대상 7, 8, -7, 0 중 하나가 거절됨";
            if (r.TryRegisterHit(7) || r.TryRegisterHit(-7) || r.TryRegisterHit(0)) return "이미 맞은 대상이 다시 등록됨";
            if (r.Count != 4) return "Count 기대 4 / 결과 " + r.Count;
            r.Clear();
            if (r.Count != 0 || !r.TryRegisterHit(7)) return "Clear 뒤에 대상 7 을 다시 등록하지 못함";
            return null;
        });

        Run("hit-registry-large-ids", () =>
        {
            var r = new HitRegistry();
            if (!r.TryRegisterHit(16777216)) return "id 16777216 이 거절됨";
            if (!r.TryRegisterHit(16777217)) return "id 16777216 을 등록한 뒤 다른 대상인 16777217 이 거절됨";
            if (!r.TryRegisterHit(2000000000) || !r.TryRegisterHit(2000000001)) return "id 2000000000 을 등록한 뒤 다른 대상인 2000000001 이 거절됨";
            if (!r.TryRegisterHit(int.MaxValue) || !r.TryRegisterHit(int.MaxValue - 1) || !r.TryRegisterHit(int.MinValue) || !r.TryRegisterHit(int.MinValue + 1)) return "int 범위 양 끝의 서로 다른 id 가 같은 대상으로 처리됨";
            if (r.TryRegisterHit(16777217) || r.TryRegisterHit(2000000001)) return "이미 맞은 큰 id 가 다시 등록됨";
            if (r.Count != 8) return "Count 기대 8 / 결과 " + r.Count;
            // 서버가 발급하는 id 형태(상위 8비트 = 샤드 번호, 하위 24비트 = 일련번호)로 무작위 비교
            var rng = new System.Random(7002);
            var reference = new System.Collections.Generic.HashSet<int>();
            var reg = new HitRegistry();
            for (int i = 0; i < 3000; i++)
            {
                int id = (rng.Next(1, 100) << 24) | rng.Next(0, 64);
                bool want = reference.Add(id);
                bool got = reg.TryRegisterHit(id);
                if (got != want) return "TryRegisterHit(" + id + ") 기대 " + want + " / 결과 " + got + " (" + (i + 1) + "번째 호출)";
            }
            return reg.Count == reference.Count ? null : "Count 기대 " + reference.Count + " / 결과 " + reg.Count;
        });
    }
}

