{{USER_CODE}}

public static class __Judge
{
    static readonly System.Diagnostics.Stopwatch Clock = System.Diagnostics.Stopwatch.StartNew();
    const int TotalBudgetMs = 11500, CaseBudgetMs = 4500;
    const int StackBytes = 256 * 1024;   // 채점 환경의 메모리 한도 안에서 스레드를 여러 개 만들기 위해 스택을 작게 잡는다

    // 채점 환경은 동시에 만들 수 있는 스레드가 6개 정도로 제한된다: 케이스 스레드 1 + 작업 스레드 최대 4 만 쓴다.
    // 케이스마다 별도 스레드에서 실행하고 제한 시간 안에 끝나지 않으면 [FAIL] 로 보고한다(채점기가 멈추지 않게 한다).
    static void Run(string id, System.Func<string> body)
    {
        string err;
        int budget = (int)System.Math.Min(CaseBudgetMs, TotalBudgetMs - Clock.ElapsedMilliseconds);
        if (budget <= 0) err = "앞선 케이스들이 제한 시간을 다 써서 실행하지 못함";
        else
        {
            string result = null;
            var t = new System.Threading.Thread(() =>
            {
                try { result = body(); }
                catch (System.Exception e) { result = "예외 발생: " + e.GetType().Name; }
            }, StackBytes);
            t.IsBackground = true;
            t.Start();
            err = t.Join(budget) ? result : "시간 초과(" + budget + "ms): 호출이 돌아오지 않음";
        }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    sealed class Worker
    {
        public System.Threading.Thread T;
        public volatile bool Done;
        public bool Ok;
        public int Value;
        public long StartMs, DoneMs;   // Clock 기준: 스레드를 시작하기 직전과 본문이 끝난 직후
        public string Error;
        public bool Join(int ms) { return T.Join(ms); }
    }

    static Worker Start(System.Action<Worker> body)
    {
        var w = new Worker();
        w.T = new System.Threading.Thread(() =>
        {
            try { body(w); }
            catch (System.Exception e) { w.Error = e.GetType().Name; }
            w.DoneMs = Clock.ElapsedMilliseconds;
            w.Done = true;
        }, StackBytes);
        w.T.IsBackground = true;
        w.StartMs = Clock.ElapsedMilliseconds;
        w.T.Start();
        return w;
    }

    static Worker Enq(BoundedBlockingQueue<int> q, int item, int timeoutMs)
    {
        return Start(w => { w.Ok = q.TryEnqueue(item, timeoutMs); });
    }

    static Worker Deq(BoundedBlockingQueue<int> q, int timeoutMs)
    {
        return Start(w => { int v; w.Ok = q.TryDequeue(timeoutMs, out v); w.Value = v; });
    }

    // 워커들이 대기 상태(WaitSleepJoin)에 들어가거나 끝날 때까지 최대 1초 기다린 뒤 조금 더 둔다.
    static void Settle(params Worker[] ws)
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        while (sw.ElapsedMilliseconds < 1000)
        {
            bool all = true;
            foreach (var w in ws)
                if (!w.Done && (w.T.ThreadState & System.Threading.ThreadState.WaitSleepJoin) == 0) all = false;
            if (all) break;
            System.Threading.Thread.Sleep(1);
        }
        System.Threading.Thread.Sleep(25);
    }

    // 워커 중 하나라도 끝날 때까지 최대 ms 기다린다.
    static bool WaitAnyDone(int ms, params Worker[] ws)
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        while (sw.ElapsedMilliseconds < ms)
        {
            foreach (var w in ws) if (w.Done) return true;
            System.Threading.Thread.Sleep(1);
        }
        return false;
    }

    static bool IsArgRange(System.Action a)
    {
        try { a(); return false; }
        catch (System.ArgumentOutOfRangeException) { return true; }
    }

    public static void Main()
    {
        Run("single-thread-fifo-and-arguments", () =>
        {
            if (!IsArgRange(() => new BoundedBlockingQueue<int>(0)) || !IsArgRange(() => new BoundedBlockingQueue<int>(-3))) return "capacity 0 또는 -3 에 ArgumentOutOfRangeException 이 나지 않음";
            var q = new BoundedBlockingQueue<int>(3);
            int x = 99;
            if (q.Capacity != 3 || q.Count != 0) return "새 큐(용량 3) 기대 Capacity 3, Count 0 / 결과 " + q.Capacity + ", " + q.Count;
            if (q.TryDequeue(0, out x) || x != 0) return "빈 큐의 TryDequeue(0) 기대 false, item 0 / 결과 item " + x;
            if (!q.TryEnqueue(1, 0) || !q.TryEnqueue(2, 0) || !q.TryEnqueue(3, 0)) return "자리가 있는데 TryEnqueue(…, 0) 이 false";
            if (q.Count != 3) return "3개를 넣은 뒤 Count 기대 3 / 결과 " + q.Count;
            if (q.TryEnqueue(4, 0)) return "가득 찬 큐에서 TryEnqueue(4, 0) 이 true";
            if (q.Count != 3) return "실패한 TryEnqueue 뒤 Count 기대 3 / 결과 " + q.Count;
            if (!q.TryDequeue(0, out x) || x != 1) return "첫 TryDequeue 기대 1 / 결과 " + x;
            if (!q.TryEnqueue(5, 0)) return "하나 꺼낸 뒤 TryEnqueue(5, 0) 이 false";
            var got = new System.Collections.Generic.List<int>();
            while (q.TryDequeue(0, out x)) { got.Add(x); if (got.Count > 5) break; }
            if (string.Join(",", got) != "2,3,5") return "꺼낸 순서 기대 2,3,5 / 결과 " + string.Join(",", got);
            if (q.Count != 0) return "모두 꺼낸 뒤 Count 기대 0 / 결과 " + q.Count;
            if (!IsArgRange(() => q.TryEnqueue(1, -2))) return "TryEnqueue 의 timeoutMs -2 에 ArgumentOutOfRangeException 이 나지 않음";
            if (!IsArgRange(() => { int y; q.TryDequeue(-2, out y); })) return "TryDequeue 의 timeoutMs -2 에 ArgumentOutOfRangeException 이 나지 않음";
            if (q.Count != 0) return "잘못된 timeoutMs 호출이 큐를 바꿈";
            var s = new BoundedBlockingQueue<string>(1);
            string str = "x";
            if (s.TryDequeue(0, out str) || str != null) return "빈 string 큐의 TryDequeue(0) 가 item 을 null 로 두지 않음";
            if (!s.TryEnqueue("a", System.Threading.Timeout.Infinite) || !s.TryDequeue(System.Threading.Timeout.Infinite, out str) || str != "a") return "기다릴 필요가 없는 Timeout.Infinite 호출이 실패";
            return null;
        });

        Run("timeout-returns-false-queue-unchanged", () =>
        {
            var q = new BoundedBlockingQueue<int>(1);
            q.TryEnqueue(10, 0);
            var sw = System.Diagnostics.Stopwatch.StartNew();
            bool r = q.TryEnqueue(11, 150);
            long ms = sw.ElapsedMilliseconds;
            if (r) return "가득 찬 큐에서 TryEnqueue(11, 150) 이 true";
            if (ms < 100 || ms > 2000) return "가득 찬 큐의 TryEnqueue(11, 150) 기대 약 150ms 뒤 false / 결과 " + ms + "ms 뒤 반환";
            int x;
            if (q.Count != 1 || !q.TryDequeue(0, out x) || x != 10) return "시간 초과된 TryEnqueue 가 큐 내용을 바꿈";
            x = 99;
            sw.Restart();
            r = q.TryDequeue(150, out x);
            ms = sw.ElapsedMilliseconds;
            if (r) return "빈 큐에서 TryDequeue(150) 이 true (시간 초과된 11 이 뒤늦게 들어갔을 수 있음)";
            if (x != 0) return "시간 초과된 TryDequeue 의 item 기대 0 / 결과 " + x;
            if (ms < 100 || ms > 2000) return "빈 큐의 TryDequeue(150) 기대 약 150ms 뒤 false / 결과 " + ms + "ms 뒤 반환";
            if (!q.TryEnqueue(12, 0) || !q.TryDequeue(0, out x) || x != 12 || q.Count != 0) return "시간 초과 뒤의 넣기·꺼내기가 정상 동작하지 않음";
            return null;
        });

        Run("blocked-enqueue-resumes-after-dequeue", () =>
        {
            var q = new BoundedBlockingQueue<int>(2);
            q.TryEnqueue(1, 0); q.TryEnqueue(2, 0);
            var p = Enq(q, 3, 3000);
            Settle(p);
            if (p.Done) return "가득 찬 큐에서 TryEnqueue(3, 3000) 이 기다리지 않고 바로 반환(" + (p.Error ?? p.Ok.ToString()) + ")";
            if (q.Count != 2) return "기다리는 동안 Count 기대 2 / 결과 " + q.Count;
            int x;
            if (!q.TryDequeue(0, out x) || x != 1) return "넣는 스레드가 기다리는 동안 TryDequeue(0) 기대 1 / 결과 " + x;
            if (!p.Join(1500)) return "자리가 났는데 기다리던 TryEnqueue 가 1500ms 안에 깨어나지 않음";
            if (p.Error != null || !p.Ok) return "자리가 난 뒤 TryEnqueue 기대 true / 결과 " + (p.Error ?? "false");
            int a, b;
            if (!q.TryDequeue(0, out a) || !q.TryDequeue(0, out b) || a != 2 || b != 3) return "이후 꺼낸 순서 기대 2,3";
            return q.Count == 0 ? null : "Count 기대 0 / 결과 " + q.Count;
        });

        Run("blocked-dequeue-resumes-after-enqueue", () =>
        {
            var q = new BoundedBlockingQueue<int>(2);
            var c = Deq(q, 3000);
            Settle(c);
            if (c.Done) return "빈 큐에서 TryDequeue(3000) 이 기다리지 않고 바로 반환(" + (c.Error ?? c.Ok.ToString()) + ")";
            if (!q.TryEnqueue(42, 0)) return "꺼내는 스레드가 기다리는 동안 TryEnqueue(42, 0) 이 false";
            if (!c.Join(1500)) return "항목이 들어왔는데 기다리던 TryDequeue 가 1500ms 안에 깨어나지 않음";
            if (c.Error != null || !c.Ok || c.Value != 42) return "기다리던 TryDequeue 기대 true, 42 / 결과 " + (c.Error ?? (c.Ok + ", " + c.Value));
            // 무한 대기도 같은 방식으로 깨어나야 한다
            var c2 = Deq(q, System.Threading.Timeout.Infinite);
            Settle(c2);
            if (c2.Done) return "빈 큐에서 TryDequeue(Timeout.Infinite) 가 기다리지 않고 바로 반환";
            q.TryEnqueue(43, 0);
            if (!c2.Join(1500) || !c2.Ok || c2.Value != 43) return "Timeout.Infinite 로 기다리던 TryDequeue 가 항목 43 을 받지 못함";
            return q.Count == 0 ? null : "Count 기대 0 / 결과 " + q.Count;
        });

        Run("one-slot-wakes-exactly-one-waiter", () =>
        {
            // 용량 1, 가득 참. 넣으려는 스레드 둘이 기다린다. 한 칸만 비우면 한 스레드만 넣어야 한다.
            var q = new BoundedBlockingQueue<int>(1);
            q.TryEnqueue(1, 0);
            var p1 = Enq(q, 2, 3000); Settle(p1);
            var p2 = Enq(q, 3, 3000); Settle(p2);
            if (p1.Done || p2.Done) return "가득 찬 큐에서 TryEnqueue(…, 3000) 이 기다리지 않음";
            int x;
            if (!q.TryDequeue(0, out x) || x != 1) return "TryDequeue(0) 기대 1 / 결과 " + x;
            if (!WaitAnyDone(1500, p1, p2)) return "한 칸이 비었는데 기다리던 TryEnqueue 가 하나도 깨어나지 않음";
            System.Threading.Thread.Sleep(60);
            if (p1.Error != null || p2.Error != null) return "기다리던 TryEnqueue 에서 예외: " + (p1.Error ?? p2.Error);
            if (p1.Done && p2.Done) return "한 칸만 비었는데 기다리던 TryEnqueue 둘이 모두 반환(용량 1, Count " + q.Count + "): 깨어난 뒤 조건을 다시 확인하지 않음";
            if (q.Count != 1) return "용량 1 큐의 Count 기대 1 / 결과 " + q.Count;
            int first, second;
            if (!q.TryDequeue(0, out first)) return "두 번째 TryDequeue(0) 이 false";
            if (!p1.Join(1500) || !p2.Join(1500) || !p1.Ok || !p2.Ok) return "남은 TryEnqueue 가 끝나지 않았거나 false";
            if (!q.TryDequeue(0, out second) || first + second != 5 || first == second) return "꺼낸 값 기대 2 와 3 / 결과 " + first + ", " + second;

            // 비어 있는 큐에서 꺼내려는 스레드 둘이 기다린다. 하나만 넣으면 한 스레드만 받아야 한다.
            var e = new BoundedBlockingQueue<int>(4);
            var c1 = Deq(e, 3000); Settle(c1);
            var c2 = Deq(e, 3000); Settle(c2);
            if (c1.Done || c2.Done) return "빈 큐에서 TryDequeue(3000) 이 기다리지 않음";
            if (!e.TryEnqueue(7, 0)) return "TryEnqueue(7, 0) 이 false";
            if (!WaitAnyDone(1500, c1, c2)) return "항목이 하나 들어왔는데 기다리던 TryDequeue 가 하나도 깨어나지 않음";
            System.Threading.Thread.Sleep(60);
            if (c1.Error != null || c2.Error != null) return "항목 하나에 기다리던 TryDequeue 둘이 깨어나 예외 발생: " + (c1.Error ?? c2.Error) + " (깨어난 뒤 조건을 다시 확인하지 않음)";
            if (c1.Done && c2.Done) return "항목이 하나뿐인데 기다리던 TryDequeue 둘이 모두 반환(Count " + e.Count + "): 깨어난 뒤 조건을 다시 확인하지 않음";
            var winner = c1.Done ? c1 : c2; var other = c1.Done ? c2 : c1;
            if (!winner.Ok || winner.Value != 7) return "깨어난 TryDequeue 기대 true, 7 / 결과 " + winner.Ok + ", " + winner.Value;
            if (e.Count != 0) return "Count 기대 0 / 결과 " + e.Count;
            e.TryEnqueue(8, 0);
            if (!other.Join(1500) || other.Error != null || !other.Ok || other.Value != 8) return "남은 TryDequeue 가 다음 항목 8 을 받지 못함";
            return null;
        });

        Run("complete-wakes-waiters-and-drains", () =>
        {
            var q = new BoundedBlockingQueue<int>(2);
            q.TryEnqueue(1, 0); q.TryEnqueue(2, 0);
            var p = Enq(q, 3, 3000);
            Settle(p);
            if (p.Done) return "가득 찬 큐에서 TryEnqueue(3, 3000) 이 기다리지 않음";
            q.Complete();
            if (!p.Join(1500)) return "Complete 뒤 1500ms 안에 기다리던 TryEnqueue 가 깨어나지 않음";
            if (p.Error != null || p.Ok) return "Complete 로 깨어난 TryEnqueue 기대 false / 결과 " + (p.Error ?? "true");
            var sw = System.Diagnostics.Stopwatch.StartNew();
            if (q.TryEnqueue(9, 0) || q.TryEnqueue(9, 1000)) return "Complete 된 큐에 TryEnqueue 가 true";
            if (sw.ElapsedMilliseconds > 500) return "Complete 된 큐의 TryEnqueue(9, 1000) 이 바로 false 를 반환하지 않고 " + sw.ElapsedMilliseconds + "ms 기다림";
            if (q.Count != 2) return "Complete 뒤 Count 기대 2 / 결과 " + q.Count;
            int a, b, c = 99;
            if (!q.TryDequeue(0, out a) || !q.TryDequeue(1000, out b) || a != 1 || b != 2) return "Complete 뒤 남은 항목 기대 1,2 를 꺼내지 못함";
            sw.Restart();
            if (q.TryDequeue(1000, out c) || c != 0) return "Complete 되고 빈 큐의 TryDequeue 기대 false, item 0";
            if (sw.ElapsedMilliseconds > 500) return "Complete 되고 빈 큐의 TryDequeue(1000) 이 바로 false 를 반환하지 않고 " + sw.ElapsedMilliseconds + "ms 기다림";
            q.Complete();
            if (q.TryEnqueue(9, 0) || q.Count != 0) return "Complete 를 두 번 호출한 뒤 상태가 바뀜";

            var e = new BoundedBlockingQueue<int>(2);
            var c1 = Deq(e, 3000); var c2 = Deq(e, System.Threading.Timeout.Infinite);
            Settle(c1, c2);
            if (c1.Done || c2.Done) return "빈 큐에서 TryDequeue 가 기다리지 않음";
            e.Complete();
            if (!c1.Join(1500) || !c2.Join(1500)) return "Complete 뒤 1500ms 안에 기다리던 TryDequeue 가 깨어나지 않음";
            if (c1.Error != null || c2.Error != null || c1.Ok || c2.Ok) return "Complete 로 깨어난 TryDequeue 기대 false / 결과 " + (c1.Error ?? c2.Error ?? "true");
            return null;
        });

        Run("mixed-waiters-no-lost-wakeup", () =>
        {
            // 넣는 쪽과 꺼내는 쪽이 동시에 기다리게 되는 상황. 깨워야 할 쪽이 깨어나지 않으면 시간 초과로 드러난다.
            for (int round = 0; round < 3; round++)
            {
                var q = new BoundedBlockingQueue<int>(1);
                var c1 = Deq(q, 1200); Settle(c1);
                var c2 = Deq(q, 1200); Settle(c2);
                if (c1.Done || c2.Done) return "빈 큐에서 TryDequeue(1200) 이 기다리지 않음";
                bool e1 = q.TryEnqueue(100, 0);
                var sw = System.Diagnostics.Stopwatch.StartNew();
                bool e2 = q.TryEnqueue(200, 1200);
                long ms = sw.ElapsedMilliseconds;
                if (!e1) return "빈 큐에 TryEnqueue(100, 0) 이 false";
                if (!e2 || ms > 700) return "꺼내는 스레드 둘이 기다리는 용량 1 큐에 100, 200 을 연달아 넣었는데 TryEnqueue(200, 1200) 이 " + ms + "ms 동안 진행하지 못함: 깨워야 할 스레드가 깨어나지 않음";
                if (!c1.Join(1500) || !c2.Join(1500)) return "기다리던 TryDequeue 가 끝나지 않음";
                if (c1.Error != null || c2.Error != null || !c1.Ok || !c2.Ok || c1.Value + c2.Value != 300 || c1.Value == c2.Value)
                    return "기다리던 TryDequeue 둘 기대 100 과 200 / 결과 " + (c1.Error ?? (c1.Ok + " " + c1.Value)) + ", " + (c2.Error ?? (c2.Ok + " " + c2.Value));

                var f = new BoundedBlockingQueue<int>(1);
                f.TryEnqueue(1, 0);
                var p1 = Enq(f, 2, 1200); Settle(p1);
                var p2 = Enq(f, 3, 1200); Settle(p2);
                if (p1.Done || p2.Done) return "가득 찬 큐에서 TryEnqueue(…, 1200) 이 기다리지 않음";
                int a, b, c;
                bool d1 = f.TryDequeue(0, out a);
                sw.Restart();
                bool d2 = f.TryDequeue(1200, out b);
                bool d3 = f.TryDequeue(1200, out c);
                ms = sw.ElapsedMilliseconds;
                if (!d1 || a != 1) return "가득 찬 큐의 TryDequeue(0) 기대 1";
                if (!d2 || ms > 700) return "넣는 스레드 둘이 기다리는 용량 1 큐에서 연달아 꺼냈는데 TryDequeue(1200) 두 번이 " + ms + "ms 동안 진행하지 못함: 깨워야 할 스레드가 깨어나지 않음";
                if (!d3 || b + c != 5 || b == c) return "이어서 꺼낸 값 기대 2 와 3 / 결과 " + b + ", " + (d3 ? c.ToString() : "시간 초과");
                if (!p1.Join(1500) || !p2.Join(1500) || !p1.Ok || !p2.Ok) return "기다리던 TryEnqueue 가 true 로 끝나지 않음";
            }
            return null;
        });

        Run("timeout-is-total-across-wakeups", () =>
        {
            // 기다리는 스레드를 "조건은 여전히 거짓인 채로" 20ms 마다 깨운다: 넣자마자 도로 꺼내거나(꺼내는 쪽 검사), 꺼내자마자 도로 채운다(넣는 쪽 검사).
            // 제한 시간 300ms 는 처음 호출한 때부터 한 번만 흘러야 한다. 깨어날 때마다 300ms 를 새로 기다리면 깨우는 동안에는 영영 끝나지 않는다.
            for (int side = 0; side < 2; side++)
            {
                string name = side == 0 ? "빈 큐의 TryDequeue(300)" : "가득 찬 큐의 TryEnqueue(…, 300)";
                for (int attempt = 0; attempt < 3; attempt++)
                {
                    var q = new BoundedBlockingQueue<int>(1);
                    if (side == 1) q.TryEnqueue(1, 0);
                    var w = side == 0 ? Deq(q, 300) : Enq(q, 2, 300);
                    Settle(w);
                    if (w.Done) return name + " 이 기다리지 않고 바로 반환";
                    bool taken = false;   // 기다리던 스레드가 그 틈에 항목(자리)을 가져갔다: 올바른 동작이므로 이 시도로는 판정하지 않는다
                    int x;
                    while (!w.Done && Clock.ElapsedMilliseconds - w.StartMs < 1100)
                    {
                        if (side == 0) { if (!q.TryEnqueue(1, 0)) { taken = true; break; } if (!q.TryDequeue(0, out x)) { taken = true; break; } }
                        else { if (!q.TryDequeue(0, out x)) { taken = true; break; } if (!q.TryEnqueue(1, 0)) { taken = true; break; } }
                        System.Threading.Thread.Sleep(20);
                    }
                    if (!taken && !w.Done) return name + " 이 1100ms 가 지나도 반환하지 않음: 깨어날 때마다 timeoutMs 전체를 다시 기다리고 있음(남은 시간만 기다려야 함)";
                    if (!w.Join(1500)) return name + " 이 끝나지 않음";
                    if (w.Error != null) return name + " 에서 예외: " + w.Error;
                    if (taken || w.Ok) continue;
                    long waited = w.DoneMs - w.StartMs;
                    if (waited < 250) return name + " 이 " + waited + "ms 만에 false 반환: 깨어났을 때 조건이 거짓이면 남은 시간만큼 다시 기다려야 함";
                    break;
                }
            }
            return null;
        });

        Run("stress-two-producers-two-consumers", () =>
        {
            // 용량 1: 넣는 쪽과 꺼내는 쪽이 번갈아 기다리게 되어, 잘못 깨우는 구현은 금방 모두 멈춘다
            const int producers = 2, consumers = 2, per = 8000, total = producers * per;
            var q = new BoundedBlockingQueue<int>(1);
            var seen = new int[total];
            string bad = null;
            int tickets = 0;
            var ws = new System.Collections.Generic.List<Worker>();
            for (int i = 0; i < producers; i++)
            {
                int pi = i;
                ws.Add(Start(w =>
                {
                    for (int k = 0; k < per; k++)
                        if (!q.TryEnqueue(pi * per + k, 2000)) { bad = "생산자 " + pi + " 의 " + k + "번째 TryEnqueue(…, 2000) 이 false(2초 동안 자리가 나지 않음)"; return; }
                }));
            }
            for (int i = 0; i < consumers; i++)
            {
                ws.Add(Start(w =>
                {
                    var last = new int[producers];
                    for (int j = 0; j < producers; j++) last[j] = -1;
                    while (System.Threading.Interlocked.Increment(ref tickets) <= total)
                    {
                        int v;
                        if (!q.TryDequeue(2000, out v)) { bad = "TryDequeue(2000) 이 false(2초 동안 항목이 오지 않음)"; return; }
                        if (v < 0 || v >= total) { bad = "넣은 적 없는 값 " + v + " 이 나옴"; return; }
                        System.Threading.Interlocked.Increment(ref seen[v]);
                        int pi = v / per, k = v % per;
                        if (k <= last[pi]) { bad = "생산자 " + pi + " 의 항목 순서가 뒤바뀜: " + last[pi] + " 다음에 " + k; return; }
                        last[pi] = k;
                    }
                }));
            }
            var sw = System.Diagnostics.Stopwatch.StartNew();
            while (sw.ElapsedMilliseconds < 3800)
            {
                bool allDone = true;
                foreach (var w in ws) if (!w.Done) allDone = false;
                if (allDone) break;
                int n = q.Count;
                if (n < 0 || n > 1) return "실행 도중 용량 1 큐의 Count 가 0~1 범위를 벗어남: " + n;
                System.Threading.Thread.Sleep(1);
            }
            foreach (var w in ws) if (w.Error != null) return "작업 스레드에서 예외: " + w.Error;
            if (bad != null) return bad;
            foreach (var w in ws) if (!w.Done) return "시간 초과(3800ms): 생산자 2 x 소비자 2 가 " + total + "개를 다 옮기지 못함";
            for (int v = 0; v < total; v++) if (seen[v] != 1) return "항목 " + v + " 이 " + seen[v] + "번 나옴(기대 1번)";
            return q.Count == 0 ? null : "끝난 뒤 Count 기대 0 / 결과 " + q.Count;
        });
    }
}

followUps.keyAnswer:
- **왜 틀리나:** 비교와 대입이 따로다. 스레드 A(피해 900)와 B(피해 950)가 둘 다 `_best` = 800 을 읽고 비교를 통과한 뒤, B 가 950 을 쓰고 A 가 900 을 덮어쓰면 기록이 **낮아진다.** 확인 후 변경(check-then-act) 경쟁이다.
- **CAS 로 고치기:** `Interlocked.CompareExchange(ref 위치, 새값, 기대값)` 은 위치의 값이 기대값과 같을 때만 새 값으로 바꾸고, 바꾸기 전의 값을 돌려준다. 이 전체가 원자적이다.

```csharp
public bool TryRecord(int damage)
{
    while (true)
    {
        int seen = Volatile.Read(ref _best);
        if (damage <= seen) return false;                    // 갱신할 필요 없음
        if (Interlocked.CompareExchange(ref _best, damage, seen) == seen)
            return true;                                     // 내가 본 값 그대로였으므로 교체 성공
        // 그 사이 다른 스레드가 바꿨다: 새 값을 읽고 다시 판단한다
    }
}
```

- **왜 올바른가:** 교체는 "내가 판단의 근거로 삼은 값이 아직 그대로일 때"만 일어난다. 실패하면 최신 값으로 다시 비교하므로 더 높은 기록을 낮은 값으로 덮을 수 없다.
- **한계:** 변수 하나에 대한 연산 하나만 원자적이다. "최고 피해"와 "그 기록의 플레이어 id"를 함께 바꿔야 한다면 `Interlocked` 두 번으로는 안 되고, 둘을 묶은 불변 객체의 참조를 CAS 로 교체하거나 `lock` 을 써야 한다.
- **ABA 문제:** CAS 는 "값이 같은가"만 본다. 락 없는 스택에서 스레드 1 이 top = A, A.next = B 를 읽고 멈춘 사이, 스레드 2 가 A 와 B 를 꺼내고 A 를 다시 넣으면 top 은 다시 A 다. 스레드 1 의 CAS(top: A → B)는 성공하지만 B 는 이미 스택에 없는 노드다. 값은 같아 보여도 그 사이 상태가 바뀌었다는 것을 CAS 가 알아채지 못하는 문제다.
- **대처:** 포인터와 함께 버전 카운터를 묶어 비교하거나, 다른 스레드가 참조 중인 노드가 재사용되지 않도록 메모리 회수를 관리한다. Wikipedia 의 ABA 문서는 회수를 미루는 방법의 하나로 자동 가비지 컬렉터가 있는 환경에서 알고리즘을 실행하는 것도 든다.
- **실무 결론:** 락 없는 자료구조는 직접 만들지 말고 검증된 `ConcurrentQueue<T>` / `ConcurrentStack<T>` 를 쓴다.
